  worldType: "flat",
  difficulty: "normal",
  hardcore: false,
  dayClock: 60,
  tick: 100,
  players: [{ id: "acct-1", name: "Alpha", skinId: null, x: 5, y: 40, z: 5, yaw: 0 }]
};

function worldSync(players: WorldSync["players"], overrides: Partial<WorldSync> = {}): WorldSync {
  return {
    t: "worldSync",
    tick: 100,
    dayClock: 60,
    changes: [],
    blockEntities: [],
    lootedChests: [],
    mobs: [],
    liveMobs: [],
