1	import { describe, expect, test } from "bun:test";
2	import { PROTOCOL_VERSION, type ServerMessage, type WorldSync } from "@/lib/net/protocol";
3	import { gunzipWorldSync } from "@/lib/net/codec";
4	import type { TicketClaims } from "@/lib/net/tickets";
5	import { createMemoryPersistence, parseSaveBlob } from "./persistence";
6	import { Room, type ClientSink } from "./room";
7	
8	/**
9	 * The room's contracts, exercised through fake sockets against the in-memory
10	 * persistence — every joined client is a scripted sink, every tick is driven
11	 * by hand (no real timers), and the world is a real (small… no — full-size)
12	 * engine. Room construction takes a couple of seconds (worldgen); the suite
13	 * shares one room per describe where isolation allows.
14	 */
15	
16	type Frame = { kind: "text"; message: ServerMessage } | { kind: "binary"; sync: Promise<WorldSync | null> } | { kind: "close"; code: number };
17	
18	function fakeSink(): ClientSink & { frames: Frame[]; messagesOf<T extends ServerMessage["t"]>(t: T): Array<Extract<ServerMessage, { t: T }>> } {
19	  const frames: Frame[] = [];
20	  return {
21	    frames,
22	    send(data) {
23	      if (typeof data === "string") frames.push({ kind: "text", message: JSON.parse(data) as ServerMessage });
24	      else frames.push({ kind: "binary", sync: gunzipWorldSync(data) });
25	    },
26	    close(code) {
27	      frames.push({ kind: "close", code });
28	    },
29	    bufferedAmount: () => 0,
30	    messagesOf<T extends ServerMessage["t"]>(t: T) {
31	      return frames
32	        .filter((f): f is Extract<Frame, { kind: "text" }> => f.kind === "text")
33	        .map((f) => f.message)
34	        .filter((m): m is Extract<ServerMessage, { t: T }> => m.t === t);
35	    }
36	  };
37	}
38	
39	function claimsFor(id: string, wid: string, role: "owner" | "member" = "member"): TicketClaims {
40	  return { sub: id, wid, name: id.toUpperCase(), skinId: null, role, pv: PROTOCOL_VERSION, iat: 0, exp: 9999999999 };
41	}
42	
43	const move = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, crouch: false };
44	
45	async function makeRoom(worldId = "w1") {
46	  const persistence = createMemoryPersistence();
47	  const record = await persistence.loadWorld(worldId);
48	  const room = new Room(record!, persistence, () => 0);
49	  return { room, persistence };
50	}
51	
52	describe("room lifecycle", () => {
53	  test("join → welcome + gzipped world sync; a second join is announced to the first", async () => {
54	    const { room } = await makeRoom();
55	    const a = fakeSink();
56	    expect(await room.join(claimsFor("alice", "w1", "owner"), a)).toBe(true);
57	
58	    const welcome = a.messagesOf("welcome")[0];
59	    expect(welcome).toMatchObject({ protocol: PROTOCOL_VERSION, playerId: "alice", worldId: "w1" });
60	    expect(welcome.seed).toBeGreaterThan(0);
61	
62	    const binary = a.frames.find((f) => f.kind === "binary");
63	    expect(binary).toBeTruthy();
64	    const sync = await (binary as Extract<Frame, { kind: "binary" }>).sync;
65	    expect(sync).toMatchObject({ t: "worldSync" });
66	    expect(Array.isArray(sync!.changes)).toBe(true);
67	
68	    const b = fakeSink();
69	    await room.join(claimsFor("bob", "w1"), b);
70	    expect(a.messagesOf("playerJoined")[0]?.player.id).toBe("bob");
71	    expect(room.playerCount()).toBe(2);
72	  });
73	
74	  test("a 9th join is refused with ROOM_FULL", async () => {
75	    const { room } = await makeRoom();
76	    for (let i = 0; i < 8; i += 1) expect(await room.join(claimsFor(`p${i}`, "w1"), fakeSink())).toBe(true);
77	    const ninth = fakeSink();
78	    expect(await room.join(claimsFor("p9", "w1"), ninth)).toBe(false);
79	    expect(ninth.frames.find((f) => f.kind === "close")).toMatchObject({ code: 4002 });
80	  });
81	
82	  test("block edits propagate: one player's placeBlock reaches the other as a tick event", async () => {
83	    const { room } = await makeRoom();
84	    const a = fakeSink();
85	    const b = fakeSink();
86	    await room.join(claimsFor("alice", "w1", "owner"), a);
87	    await room.join(claimsFor("bob", "w1"), b);
88	    // Aim alice straight down at the block underfoot and give her a mined-out
89	    // path… simpler: force a block change through the engine's own dispatch
90	    // (the same door a cmd message takes) and let the tick broadcast it.
91	    const alice = room.engine.state.players.get("alice")!;
92	    alice.inventory = [...alice.inventory];
93	    room.engine.state.blockChanges.set(5, 5, 5, 1);
94	    room.engine.state.worldMeshDirty = true;
95	    (room.engine as unknown as { emit: (e: unknown) => void }).emit({ type: "blockPlaced", blockId: 1, x: 5, y: 5, z: 5 });
96	    (room as unknown as { tick(dt: number): void }).tick(0.05);
97	
98	    const tickB = b.messagesOf("tick").at(-1);
99	    expect(tickB?.ev.some((e) => e.type === "blockPlaced" && e.x === 5)).toBe(true);
100	    // …and bob's tick carries alice's pose, not his own.
101	    expect(tickB?.pp.some((p) => p.id === "alice")).toBe(true);
102	    expect(tickB?.pp.some((p) => p.id === "bob")).toBe(false);
103	  });
104	
105	  test("a speed-hacked pose is refused and answered with forcePose; an honest one sticks", async () => {
106	    const { room } = await makeRoom();
107	    const a = fakeSink();
108	    await room.join(claimsFor("alice", "w1"), a);
109	    const alice = room.engine.state.players.get("alice")!;
110	    const { x, y, z } = alice.position;
111	
112	    await room.handleMessage("alice", { t: "pose", seq: 1, x: x + 0.4, y, z, yaw: 0.3, pitch: 0, onGround: true, move, mineHeld: false });
113	    expect(alice.position.x).toBeCloseTo(x + 0.4, 6);
114	    expect(a.messagesOf("forcePose")).toHaveLength(0);
115	
116	    await room.handleMessage("alice", { t: "pose", seq: 2, x: x + 90, y, z: z + 90, yaw: 0, pitch: 0, onGround: true, move, mineHeld: false });
117	    expect(alice.position.x).toBeCloseTo(x + 0.4, 6); // unmoved
118	    expect(a.messagesOf("forcePose")).toHaveLength(1);
119	
120	    // Stale seq replay is silently dropped.
121	    await room.handleMessage("alice", { t: "pose", seq: 2, x: x + 1, y, z, yaw: 0, pitch: 0, onGround: true, move, mineHeld: false });
122	    expect(alice.position.x).toBeCloseTo(x + 0.4, 6);
123	  });
124	
125	  test("self-deltas ship only on change; chat is rate-limited and broadcast", async () => {
126	    const { room } = await makeRoom();
127	    const a = fakeSink();
128	    const b = fakeSink();
129	    await room.join(claimsFor("alice", "w1"), a);
130	    await room.join(claimsFor("bob", "w1"), b);
131	    const roomTick = () => (room as unknown as { tick(dt: number): void }).tick(0.05);
132	
133	    roomTick(); // first tick: full self snapshot
134	    const first = a.messagesOf("tick").at(-1);
135	    expect(first?.self?.hearts).toBeDefined();
136	    roomTick(); // nothing changed → no self at all (or an empty-free tick)
137	    const second = a.messagesOf("tick").at(-1);
138	    expect(second?.self).toBeUndefined();
139	
140	    const alice = room.engine.state.players.get("alice")!;
141	    alice.hearts = 5;
142	    roomTick();
143	    expect(a.messagesOf("tick").at(-1)?.self?.hearts).toBe(5);
144	
145	    for (let i = 0; i < 5; i += 1) await room.handleMessage("alice", { t: "chat", text: `hi ${i}` });
146	    const bobChats = b.messagesOf("chat");
147	    expect(bobChats).toHaveLength(3); // 3/s budget
148	    expect(bobChats[0]).toMatchObject({ from: "alice", name: "ALICE" });
149	  });
150	
151	  test("leave persists the player's slice; rejoin restores it; shutdown stores the merged world", async () => {
152	    const { room, persistence } = await makeRoom();
153	    const a = fakeSink();
154	    await room.join(claimsFor("alice", "w1"), a);
155	    const alice = room.engine.state.players.get("alice")!;
156	    alice.xp = 77;
157	    room.leave("alice");
158	    expect(room.playerCount()).toBe(0);
